THOUGHT: Good, the PutWithTTL method is still correctly setting the Expire field with the TTL value. My fix addresses the issue where a regular Put operation wouldn't clear an existing TTL.

To summarize the issue and fix:
1. Issue: When a key that previously had a TTL (set with PutWithTTL) was updated with a regular Put operation, it would retain its expiration time instead of having no expiration.
2. Fix: Modified the Put method to explicitly set `record.Expire = 0` when updating a key, ensuring that regular Put operations clear any existing TTL.

Let me create a simple test script to demonstrate the issue and verify the fix:

```bash
cat <<'EOF' > ttl_fix_test.go
package main

import (
	"fmt"
	"time"
)

// Simulating the LogRecord structure
type LogRecord struct {
	Key    []byte
	Value  []byte
	Type   byte
	Expire int64
}

const LogRecordNormal = 0
const LogRecordDeleted = 1

func (lr *LogRecord) IsExpired(now int64) bool {
	return lr.Expire > 0 && lr.Expire <= now
}

// Simulating the Put operation (fixed version)
func PutFixed(record *LogRecord, key []byte, value []byte) {
	record.Key, record.Value = key, value
	record.Type, record.Expire = LogRecordNormal, 0 // Fixed: explicitly clear expiration
}

// Simulating the Put operation (buggy version)
func PutBuggy(record *LogRecord, key []byte, value []byte) {
	record.Key, record.Value = key, value
	record.Type = LogRecordNormal
	// Bug: doesn't reset Expire field
}

// Simulating the PutWithTTL operation
func PutWithTTL(record *LogRecord, key []byte, value []byte, ttl time.Duration) {
	record.Key, record.Value = key, value
	record.Type, record.Expire = LogRecordNormal, time.Now().Add(ttl).UnixNano()
}

func main() {
	fmt.Println("Testing TTL behavior with Put operations...")

	// Create a record
	record := &LogRecord{}

	// Set with TTL of 1 second
	fmt.Println("\n1. Setting key with 1-second TTL...")
	PutWithTTL(record, []byte("test"), []byte("value"), time.Second)
	fmt.Printf("   Expire time: %d\n", record.Expire)

	// Wait 2 seconds
	fmt.Println("2. Waiting 2 seconds...")
	time.Sleep(2 * time.Second)
	now := time.Now().UnixNano()
	fmt.Printf("   Current time: %d\n", now)
	fmt.Printf("   Record expired: %t\n", record.IsExpired(now))

	// Update with regular Put (buggy version)
	fmt.Println("\n3. Updating with regular Put (buggy version)...")
	PutBuggy(record, []byte("test"), []byte("new_value"))
	fmt.Printf("   Expire time: %d\n", record.Expire)
	fmt.Printf("   Record expired (should be false but is true): %t\n", record.IsExpired(now))

	// Reset for correct test
	record = &LogRecord{}
	PutWithTTL(record, []byte("test"), []byte("value"), time.Second)
	time.Sleep(2 * time.Second)
	now = time.Now().UnixNano()

	// Update with regular Put (fixed version)
	fmt.Println("\n4. Updating with regular Put (fixed version)...")
	PutFixed(record, []byte("test"), []byte("new_value"))
	fmt.Printf("   Expire time: %d\n", record.Expire)
	fmt.Printf("   Record expired (correctly false): %t\n", record.IsExpired(now))
}
EOF
```

